declare global {
  // ----------- < Связи занятий (LessonConnection) > -----------

  /**
   * Полиморфная связь занятия с другими занятиями.
   * Дискриминатор - поле type.
   *
   * Требования к области определения (scope) по типам:
   *
   * | type             | смысл                       | требования к scope            |
   * |------------------|-----------------------------|-------------------------------|
   * | subject_union    | объединить с другим предметом  | предмет + ровно один тип занятий |
   * | the_same_day_as  | поставить в один день         | ровно один тип занятий           |
   * | alternate_with   | чередовать                    | ровно один тип занятий           |
   * | different_day_as | разнести по разным дням        | указан предмет                   |
   * | unite_groups     | объединить группы на занятиях  | предмет + группы                 |
   */
  type LessonConnection =
    | SubjectUnionConnection
    | TheSameDayAsConnection
    | AlternateWithConnection
    | DifferentDayAsConnection
    | UniteGroupsConnection;

  /**
   * Связь говорит с каким предметом нужно объеденить занятия.
   * Требования к scope: предмет + ровно один тип занятий.
   */
  interface SubjectUnionConnection {
    type: "subject_union";
    connectionSubjects: {
      /**
       * С каким предметом надо объеденить занятия
       */
      subject: Subject;
      studyGroups: {
        /**
         * Какие группы (из области определения) должны ходить на объединенный
         * предмет. null - все группы из области определения.
         */
        whatGroups: StudyGroup[] | null;
        /**
         * С какими группами (из групп предмета, с которым объединяем) должны
         * ходить на объединенный предмет.
         */
        whichGroups: StudyGroup[];
      }[];
      /**
       * Какого типа занятия надо объеденить
       */
      lessonType: LessonType;
    };
  }

  /**
   * Связь говорит с какого типа занятиями, у каких групп, какого предмета
   * нужно поставить в один день с занятиями из области определения.
   * Требования к scope: ровно один тип занятий.
   * Если предмет не указан, то учитывается только тип занятий.
   * Группы указываются только если они указаны в области определения.
   */
  interface TheSameDayAsConnection {
    type: "the_same_day_as";
    connectionSubjects: {
      /**
       * С занятиями по какому предмету должны стоять занятия в один день.
       * null - по всем предметам.
       */
      subject: Subject | null;
      /**
       * У каких групп поставить занятия в один день, с занятиями групп из
       * области определения.
       * null и предмет тот же, что в scope - берутся все группы из scope.
       * null и предмет отличается - берутся все группы предмета.
       */
      studyGroups: StudyGroup[] | null;
      lessonType: LessonType;
    };
  }

  /**
   * Связь говорит с чем нужно чередовать занятия.
   * Требования к scope: ровно один тип занятий.
   */
  interface AlternateWithConnection {
    type: "alternate_with";
    connectionSubjects: {
      /**
       * Если null - берется предмет из области определения.
       */
      subject: Subject | null;
      /**
       * Какого типа занятия чередовать
       */
      lessonType: LessonType;
      /**
       * У каких групп чередовать занятия с занятиями групп из области
       * определения.
       * null и предмет тот же, что в scope - все группы из scope.
       * null и предмет отличается - все группы предмета.
       */
      studyGroups: StudyGroup[] | null;
    };
  }

  /**
   * Связь говорит у каких групп, какого предмета нужно поставить занятия в
   * разные дни с занятиями из области определения.
   * Требования к scope: указан предмет.
   */
  interface DifferentDayAsConnection {
    type: "different_day_as";
    connectionSubjects: {
      /**
       * С занятиями по каким предметам поставить в разные дни.
       * null - не учитывается.
       */
      subjects: Subject[] | null;
      /**
       * С какими группами ставить занятия в разные дни с занятиями групп из
       * области определения.
       */
      studyGroups: StudyGroup[] | null;
    };
  }

  /**
   * Связь говорит какие группы надо объеденить, на тех типах занятий, что
   * указаны в области определения условия.
   * Требования к scope: предмет + группы.
   * Для каждого указанного типа занятий отдельно будет произведено объединение.
   */
  interface UniteGroupsConnection {
    type: "unite_groups";
    connectionSubjects: {
      /**
       * Группы предмета, которые надо объеденить с группами из области
       * определения.
       */
      studyGroups: StudyGroup[];
    };
  }

  // ----------- </ Связи занятий (LessonConnection) > -----------
}

export {};